package it.andreademartini.trading.backtest.patternv2;

import static it.andreademartini.trading.backtest.patternv1.PatternV1TestSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import static it.andreademartini.trading.backtest.patternv2.MarketRegimeAnalysis.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import it.andreademartini.trading.config.TradingSystemProperties;
import it.andreademartini.trading.marketdata.HistoricalBar;
import it.andreademartini.trading.risk.*;
import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

class MarketRegimeTest {
    @TempDir Path directory;
    final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();
    PatternV2Configuration config() throws Exception {var c=PatternV2Configuration.baseline(configuration(),new TradingSystemProperties().getRisk());ObjectNode json=mapper.valueToTree(c);var g=(ObjectNode)json.path("global");g.put("startDate",START.toString());g.put("endDate",START.plusDays(400).toString());return mapper.treeToValue(json,PatternV2Configuration.class);}
    MarketRegimeIndicators.Value value(Double adx,double plus,double minus,double ema20,double ema50,double ema200){return new MarketRegimeIndicators.Value(adx,plus,minus,ema20,ema50,ema200,2.0,110.0);}
    @ParameterizedTest @CsvSource({"19.999,30,20,110,105,100,SIDEWAYS_WEAK_TREND","20,30,20,110,105,100,TRANSITION","24.999,30,20,110,105,100,TRANSITION","25,30,20,110,105,100,STRONG_UPTREND","25,20,30,90,95,100,STRONG_DOWNTREND","25,30,20,100,105,100,MIXED_UNCLASSIFIED","25,20,20,110,105,100,MIXED_UNCLASSIFIED"})
    void regimesAreExclusive(double adx,double plus,double minus,double fast,double medium,double slow,String regime){assertEquals(regime,classify(value(adx,plus,minus,fast,medium,slow),"LONG").marketRegime());}
    @ParameterizedTest @CsvSource({"LONG,30,20,WITH_TREND","LONG,20,30,COUNTER_TREND","SHORT,20,30,WITH_TREND","SHORT,30,20,COUNTER_TREND","LONG,20,20,NEUTRAL_OR_MIXED"})
    void diDirectionAgainstTrade(String direction,double plus,double minus,String expected){assertEquals(expected,classify(value(25.0,plus,minus,110,105,100),direction).withOrCounterTrend());assertEquals("NEUTRAL_OR_MIXED",classify(value(24.999,plus,minus,110,105,100),direction).withOrCounterTrend());}
    @Test void missingDataIsNotWeakTrendAndSecondaryRemainsAvailable(){var v=new MarketRegimeIndicators.Value(30.0,25.0,10.0,110.0,105.0,null,2.0,112.0);var c=classify(v,"LONG");assertEquals("INSUFFICIENT_DATA",c.marketRegime());assertEquals("DIRECTIONAL_UP",c.secondaryRegime());assertNull(c.closeAboveEMA200());assertEquals("INSUFFICIENT_DATA",classify(null,"SHORT").marketRegime());}
    @Test void secondaryTrendDoesNotRequireAlignedEmas(){var c=classify(value(30.0,30,20,100,105,100),"SHORT");assertEquals("MIXED_UNCLASSIFIED",c.marketRegime());assertEquals("DIRECTIONAL_UP",c.secondaryRegime());assertEquals("COUNTER_TREND",c.withOrCounterTrend());assertEquals("COUNTER_TREND",c.emaWithOrCounterTrend());assertTrue(c.closeAboveEMA20());assertFalse(c.ema20AboveEMA50());}
    @ParameterizedTest @CsvSource({"0,ADX < 15","14.999,ADX < 15","15,15 <= ADX < 20","20,20 <= ADX < 25","25,25 <= ADX < 30","30,30 <= ADX < 40","40,ADX >= 40","100,ADX >= 40"})
    void bucketBoundaries(double adx,String expected){assertEquals(expected,bucket(adx));assertEquals("INSUFFICIENT_DATA",bucket(null));}
    @Test void trueRangeIncludesUpAndDownGaps(){assertEquals(0,bd("5").compareTo(BollingerAtr.trueRange(bar("AAPL",0,14,15,13,14),bd("10"))));assertEquals(0,bd("5").compareTo(BollingerAtr.trueRange(bar("AAPL",0,6,7,5,6),bd("10"))));}
    @Test void atrAndDiUseWilderWithExactWarmup() throws Exception {var i=new MarketRegimeIndicators(config());for(int n=0;n<14;n++){var v=i.onBar(bar("AAPL",n,100+n,101+n,99+n,100+n));assertNull(v.atr14());assertNull(v.plusDI14());assertNull(v.adx14());}var first=i.onBar(bar("AAPL",14,114,115,113,114));assertEquals(2,first.atr14(),1e-12);assertEquals(50,first.plusDI14(),1e-12);assertEquals(0,first.minusDI14(),1e-12);for(int n=15;n<27;n++)assertNull(i.onBar(bar("AAPL",n,100+n,101+n,99+n,100+n)).adx14());assertEquals(100,i.onBar(bar("AAPL",27,127,128,126,127)).adx14(),1e-12);assertEquals(100,i.onBar(bar("AAPL",28,128,129,127,128)).adx14(),1e-12);}
    @Test void zeroRangesAndEqualDirectionalMovementDoNotDivideByZero() throws Exception {var i=new MarketRegimeIndicators(config());MarketRegimeIndicators.Value v=null;for(int n=0;n<30;n++)v=i.onBar(bar("AAPL",n,100,100,100,100));assertEquals(0,v.adx14());assertEquals(0,v.plusDI14());assertEquals(0,v.minusDI14());assertEquals(0,v.atr14());}
    @Test void emaSmaSeedsAndLinearAnalyticReferencesAtEveryPeriod() throws Exception {var i=new MarketRegimeIndicators(config());for(int n=0;n<240;n++){var v=i.onBar(bar("AAPL",n,n+1,n+2,n+.5,n+1));if(n<19)assertNull(v.ema20());else assertEquals(n+1-19.0/2,v.ema20(),1e-10);if(n<49)assertNull(v.ema50());else assertEquals(n+1-49.0/2,v.ema50(),1e-10);if(n<199)assertNull(v.ema200());else assertEquals(n+1-199.0/2,v.ema200(),1e-10);assertEquals(n>=199,v.complete());}}
    @Test void wilderAdxAndDiMatchIndependentTaLibPublishedRegression() throws Exception {
        var json=mapper.readTree(getClass().getResourceAsStream("/market-regime/ta-lib-reference.json"));var stream=new MarketRegimeIndicators(config());var values=new ArrayList<MarketRegimeIndicators.Value>();
        for(int n=0;n<32;n++)values.add(stream.onBar(bar("AAPL",n,json.path("open").get(n).asDouble(),json.path("high").get(n).asDouble(),json.path("low").get(n).asDouble(),json.path("close").get(n).asDouble())));
        assertEquals(20.3781,values.get(14).plusDI14(),1e-4);assertEquals(30.1684,values.get(14).minusDI14(),1e-4);assertEquals(22.1073,values.get(27).plusDI14(),1e-4);assertEquals(20.3746,values.get(28).plusDI14(),1e-4);assertEquals(24.969182,values.get(28).minusDI14(),1e-4);assertEquals(23.0000,values.get(27).adx14(),.002);assertEquals(22.0802,values.get(28).adx14(),.002);
    }
    @Test void futureBarsCannotChangeSignalIndicatorsAndOutOfOrderIsRejected() throws Exception {var a=new MarketRegimeIndicators(config());var b=new MarketRegimeIndicators(config());MarketRegimeIndicators.Value signal=null;for(int n=0;n<210;n++){var bar=bar("AAPL",n,100+n,101+n,99+n,100+n);signal=a.onBar(bar);assertEquals(signal,b.onBar(bar));}a.onBar(bar("AAPL",210,1000,5000,1,4000));assertEquals(100,signal.adx14(),1e-10);assertThrows(IllegalArgumentException.class,()->b.onBar(bar("AAPL",209,100,101,99,100)));}
    TradeRow row(String id,double pnl,double gross,double priceR,double netR,double adx,String exit,boolean closed){return new TradeRow(id,"AAPL","BULLISH_ENGULFING","LONG",LocalDate.of(2010,1,1),START,START,closed,"2010-2013",classify(value(adx,30,20,110,105,100),"LONG"),bd(""+pnl),bd(""+gross),bd(""+priceR),closed?bd(""+netR):null,closed?outcome(bd(""+pnl)):"OPEN",exit,pnl<0?"STOP_LOSS":null,2,1.0);}
    @Test void netMetricsExcludeOpenAndDistinguishCostsBreakevenAndPriceR(){var m=metrics(List.of(row("1",100,105,1.05,1,10,"TARGET",true),row("2",-50,-45,-.45,-.5,30,"STOP",true),row("3",0,5,.05,0,20,"TIMEOUT",true),row("4",900,900,9,9,50,"OPEN",false)));assertEquals(3,m.trades());assertEquals(1,m.winners());assertEquals(1,m.losers());assertEquals(1,m.breakeven());assertEquals(1,m.openTrades());assertEquals(2,m.pfNet());assertEquals(1.0/6,m.expectancyNetR(),1e-12);assertEquals(.65/3,m.expectancyPriceR(),1e-12);assertEquals(50,m.netPnl());assertEquals(110,m.grossProfit());assertEquals(45,m.grossLoss());assertEquals(10,m.averageADXWinners());assertEquals(30,m.averageADXLosers());assertEquals(100.0/3,m.stopRate(),1e-12);assertEquals(100.0/3,m.timeoutRate(),1e-12);assertTrue(m.smallSample());}
    @Test void noLossPfAndZeroToleranceAreExplicit(){assertNull(metrics(List.of(row("1",100,105,1.05,1,10,"TARGET",true))).pfNet());assertEquals("BREAKEVEN",outcome(new BigDecimal("-0.000000001")));assertEquals("LOSER",outcome(new BigDecimal("-0.00000002")));}
    @ParameterizedTest @CsvSource({"2010-01-01,2010-2013","2013-12-31,2010-2013","2014-01-01,2014-2017","2018-01-01,2018-2021","2022-01-01,2022-END","2009-12-31,OUTSIDE_PERIODS"})
    void periodsUseSignalDate(String date,String expected){assertEquals(expected,period(LocalDate.parse(date)));}
    PatternV2Service service(){return new PatternV2Service(configuration(),new TradingSystemProperties(),null,detectors(),new PositionSizingService(new TradePricingService()),new PatternV2Store(directory));}
    Map<String,List<HistoricalBar>> bars(){var bars=new ArrayList<HistoricalBar>();for(int n=0;n<200;n++)bars.add(bar("AAPL",n,100,101,99,100));bars.add(bar("AAPL",200,100,101,98,99));bars.add(bar("AAPL",201,98.5,103,98,102));bars.add(bar("AAPL",202,100,107,99,106));return Map.of("AAPL",bars);}
    @Test void entirePortfolioExecutionsCostsAndAnalysisAreIdenticalOnOff() throws Exception {var svc=service();var c=config();var off=svc.simulate(c.withMarketRegimeAnalysis(false),bars(),"00000000-0000-0000-0000-000000000001");var on=svc.simulate(c.withMarketRegimeAnalysis(true),bars(),off.runId());assertEquals(mapper.valueToTree(off.portfolio()),mapper.valueToTree(on.portfolio()));assertEquals(off.executions(),on.executions());assertEquals(off.costs(),on.costs());assertEquals(off.analysis(),on.analysis());assertNull(off.marketRegimeAnalysis());assertNotNull(on.marketRegimeAnalysis());assertEquals(on.portfolio().summary().trades(),on.marketRegimeAnalysis().overview().stream().mapToLong(g->g.metrics().trades()).sum());assertTrue(on.marketRegimeAnalysis().signals().stream().anyMatch(s->s.status().equals("EXECUTED")));PatternV2RunComparison.requireSameTradingConfiguration(off.configuration(),on.configuration());}
    @Test void configurationPersistenceCloningAndLegacyDefault() throws Exception {var c=config().withMarketRegimeAnalysis(true);assertTrue(c.withName("New").withSymbols(c.symbols()).withGlobal(c.global()).withBollingerAtr(false,20,bd("2"),14,bd(".5")).withCapitalSkipShadowAnalysis(false).marketRegimeAnalysisEnabled());ObjectNode json=mapper.valueToTree(c);json.remove("marketRegimeAnalysisEnabled");assertFalse(mapper.treeToValue(json,PatternV2Configuration.class).marketRegimeAnalysisEnabled());var store=new PatternV2Store(directory);var saved=store.saveConfiguration(c,false);assertTrue(store.configuration(saved.id()).configuration().marketRegimeAnalysisEnabled());}
    @Test void patternAndPeriodCellsReconcileToExecutedTradesAndExport() throws Exception {var run=service().simulate(config().withMarketRegimeAnalysis(true),bars());var a=run.marketRegimeAnalysis();assertEquals(a.overview().stream().mapToLong(g->g.metrics().trades()).sum(),a.patternRegimes().stream().mapToLong(g->g.metrics().trades()).sum());assertEquals(a.overview().stream().mapToLong(g->g.metrics().trades()).sum(),a.periods().stream().mapToLong(g->g.metrics().trades()).sum());var bytes=new PatternV2ExcelExporter().export(run);try(var book=new XSSFWorkbook(new java.io.ByteArrayInputStream(bytes))){for(var name:List.of("TRADES","CONFIGURATION","EQUITY_CURVE","MARKET_REGIME_SUMMARY","ADX_BUCKETS","TREND_DIRECTION_ANALYSIS","PATTERN_REGIME_ANALYSIS","LOSER_DIAGNOSTICS","REGIME_PERIOD_ANALYSIS","MARKET_REGIME_SIGNALS"))assertNotNull(book.getSheet(name),name);var header=book.getSheet("TRADES").getRow(0);var names=new HashSet<String>();header.forEach(cell->names.add(cell.getStringCellValue()));assertTrue(names.containsAll(List.of("SignalADX14","SignalATR14","SignalMarketRegime","NetR")));}}
    @Test void frozenV1PropertiesAreNotMutatedAndModuleHasNoBrokerDependency() throws Exception {var frozen=configuration();var before=mapper.valueToTree(frozen);var svc=new PatternV2Service(frozen,new TradingSystemProperties(),null,detectors(),new PositionSizingService(new TradePricingService()),new PatternV2Store(directory));svc.simulate(config().withMarketRegimeAnalysis(true),bars());assertEquals(before,mapper.valueToTree(frozen));for(var ctor:MarketRegimeIndicators.class.getDeclaredConstructors())for(var type:ctor.getParameterTypes())assertFalse(type.getName().contains("ibkr"));}
}
